// SPEC-043 REQ-TPL-001/002: node scripts/gen-theme-templates.mjs [--check]
// Writes theme overrides for every storefront template of the default theme that the project does not hand-write, converting
// Font Awesome icons, star ratings and the home breadcrumb icon to the theme's SVG components. Twig logic, variables and element ids are
// kept as they are (core JavaScript hooks rely on them). Re-running is a no-op; --check exits 1 when a generated file is out of date.
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const CORE = join(ROOT, 'core/upload/catalog/view/theme/default/template');
const OUT = join(ROOT, 'custom/theme/ocs/template');
const MARK = '{# @generated by scripts/gen-theme-templates.mjs #}';
const CORE_VERSION = '3.0.3.7';

/** Not overridden: payment vendors' templates, e-mails (SPEC-043 Out of scope). */
const EXCLUDED = [
  /^extension\/payment\//, /^extension\/credit_card\//, /^extension\/recurring\//, /^extension\/advertise\//, /^mail\//,
  /^extension\/module\/paypal_smart_button/, /^extension\/module\/(klarna_checkout_module|amazon_login|amazon_login_error|pilibaba_button|pp_braintree_button|sagepay_direct_cards|sagepay_server_cards|divido_calculator|laybuy_layout|ebay_listing|google_hangouts)\.twig$/,
];

/** Written by hand (they carry their own @core-file header and no generated marker): never touched. */
const walk = (dir, base = '') => readdirSync(dir).flatMap((name) => {
  const p = join(dir, name);
  const rel = base ? `${base}/${name}` : name;
  return statSync(p).isDirectory() ? walk(p, rel) : rel.endsWith('.twig') ? [rel] : [];
});

const iconMap = () => {
  const php = readFileSync(join(ROOT, 'custom/extensions/ocs/upload/system/library/ocs/icons.php'), 'utf8');
  const map = {};
  for (const m of php.matchAll(/'([a-z0-9-]+)' => '(i-[a-z0-9-]+)'/g)) map[m[1]] = m[2];
  return map;
};

const svg = (symbol) => `<svg class="ocs-i" aria-hidden="true"><use href="#${symbol}"/></svg>`;

export function convert(src, map, report) {
  let s = src.replace(/\r\n/g, '\n');
  // star loops (core uses `1..5` or `5`)
  s = s.replace(/\{% for (\w+) in (?:1\.\.)?5 %\}\s*\{% if ([\w.]+) < \1 %\}[\s\S]*?fa-stack[\s\S]*?\{% endfor %\}/g,
    (m, v, x) => `<span class="ocs-stars" role="img" aria-label="{{ ${x} }} / 5">{% for ${v} in 1..5 %}<svg class="ocs-i ocs-star{% if ${x} >= ${v} %} is-on{% endif %}" aria-hidden="true"><use href="#i-star"/></svg>{% endfor %}</span>`);
  // icons: <i class="fa fa-name ..."></i>
  s = s.replace(/<i class="fa fa-([a-z0-9-]+)[^"]*"([^>]*)><\/i>/g, (m, name) => {
    if (!map[name]) report.add(`unmapped icon fa-${name}`);
    return svg(map[name] || 'i-dot');
  });
  // home breadcrumb icon comes from the core language file (text_home) as markup
  s = s.replace(/<li><a href="\{\{ breadcrumb\.href \}\}">\s*\{\{ breadcrumb\.text \}\}<\/a><\/li>/g,
    `<li><a href="{{ breadcrumb.href }}">{% if 'fa-home' in breadcrumb.text %}${svg('i-home')}{% else %}{{ breadcrumb.text }}{% endif %}</a></li>`);
  return s;
}

const leftovers = (s) => [...new Set((s.replace(/\{% if 'fa-home' in breadcrumb\.text %\}/g, '').match(/class="[^"]*\bfa\b[^"]*"|\bfa-[a-z0-9-]+/g) || []))];

export function plan() {
  const map = iconMap();
  const files = [];
  for (const rel of walk(CORE)) {
    if (EXCLUDED.some((re) => re.test(rel))) continue;
    const target = join(OUT, rel);
    if (existsSync(target) && !readFileSync(target, 'utf8').includes(MARK) && !HANDMADE_REGENERATE.has(rel)) continue; // hand-written override
    const report = new Set();
    const body = convert(readFileSync(join(CORE, rel), 'utf8'), map, report);
    const text = `{# @core-file catalog/view/theme/default/template/${rel} @core-version ${CORE_VERSION} #}\n${MARK}\n${body}`;
    files.push({ rel, target, text, report: [...report], left: leftovers(body) });
  }
  return files;
}

/** Overrides written earlier by this logic without the marker (SPEC-042): regenerated so every converted file is reproducible. */
const HANDMADE_REGENERATE = new Set([
  'common/language.twig', 'common/currency.twig', 'common/cart.twig', 'blog/menu.twig', 'blog/latest.twig', 'blog/category.twig', 'blog/review.twig', 'product/review.twig',
]);

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const files = plan();
  let stale = 0;
  let written = 0;
  for (const f of files) {
    const current = existsSync(f.target) ? readFileSync(f.target, 'utf8') : null;
    if (current === f.text) continue;
    stale++;
    if (!check) {
      mkdirSync(dirname(f.target), { recursive: true });
      writeFileSync(f.target, f.text);
      written++;
    }
  }
  const problems = files.filter((f) => f.report.length || f.left.length);
  for (const f of problems) console.log(`${f.rel}: ${[...f.report, ...f.left].join(', ')}`);
  console.log(`${files.length} generated templates, ${check ? `${stale} out of date` : `${written} written`}, ${problems.length} with leftovers`);
  process.exit(check && stale ? 1 : 0);
}
